	w := &blockedWriter{header: make(http.Header)}
	server.events(w, httptest.NewRequest(http.MethodGet, "/v1/events?conversation=slow", nil))
	if server.subscribers.Load() != 0 {
		t.Fatal("slow subscriber leaked a slot")
